import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';

interface StyledCardProps {
  $type?: 'portfolio' | 'data';
  $darkBg?: boolean;
}

export const StyledPortfolioFooterContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '16px',
  '&:not(:last-child)': {
    marginBottom: '12px',
  },
});

export const StyledCard = styled.div<StyledCardProps>(({ $type, $darkBg }) => ({
  position: 'relative',
  padding: '16px',
  borderRadius: '16px',
  height: '62px',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  backgroundColor: '#FFF',
  border: '1px solid #14141429',
  ...($type === 'portfolio' && { width: '240px' }),
  ...($type === 'data' && { width: '346px' }),
  ...($darkBg && { backgroundColor: '#E2E7EA' }),
}));

export const StyledComparisonContainer = styled.div({
  height: '17px',
  borderRadius: '999px',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  border: '1px solid #14141429',
  backgroundColor: '#FFF',
  position: 'absolute',
  top: '-9px',
  left: '8px',
  padding: '0 4px',
});

export const StyledComparisonText = styled(Paragraph)({
  fontSize: '10px',
  color: '#5C5C5C !important',
});

export const StyledSubtitle = styled(Paragraph)({
  fontSize: '12px',
  color: '#5C5C5C !important',
});

export const StyledValue = styled(Paragraph)({
  fontSize: '18px',
});
